<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\AttachProviderServiceRequest; use App\Models\Service; use App\Services\SlotCacheService; use App\Support\ApiPresenter; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class ProviderServiceController extends Controller { public function index(Request $request): JsonResponse {$p=$this->provider($request);$p->load('services');return response()->json(['data'=>$p->services->map(fn($s)=>ApiPresenter::service($s))->values()]);} public function store(AttachProviderServiceRequest $request,Service $service,SlotCacheService $cache): JsonResponse {$p=$this->provider($request);$p->services()->syncWithoutDetaching([$service->id=>['price'=>$request->validated('price'),'is_active'=>$request->boolean('is_active',true)]]);$cache->invalidate($p->id);$s=$p->services()->whereKey($service->id)->first();return response()->json(['data'=>ApiPresenter::service($s)],201);} public function update(AttachProviderServiceRequest $request,Service $service,SlotCacheService $cache): JsonResponse {$p=$this->provider($request);abort_unless($p->services()->whereKey($service->id)->exists(),404);$p->services()->updateExistingPivot($service->id,['price'=>$request->validated('price'),'is_active'=>$request->boolean('is_active',true)]);$cache->invalidate($p->id);return response()->json(['data'=>ApiPresenter::service($p->services()->whereKey($service->id)->first())]);} public function destroy(Request $request,Service $service,SlotCacheService $cache): JsonResponse {$p=$this->provider($request);$p->services()->updateExistingPivot($service->id,['is_active'=>false]);$cache->invalidate($p->id);return response()->json(['message'=>'Provider service deactivated.']);} private function provider(Request $request){return $request->user()->provider ?: abort(403,'Provider profile required.');} }
